interface Encoder {
  encode(values: string[]): string;
}
abstract class ExportJob {
  protected abstract createEncoder(): Encoder;
  run(values: string[]) {
    const clean = values.map((value) => value.trim());
    return this.createEncoder().encode(clean);
  }
}
class JsonJob extends ExportJob {
  protected createEncoder(): Encoder {
    return { encode: (values) => JSON.stringify(values) };
  }
}
class PipeJob extends ExportJob {
  protected createEncoder(): Encoder {
    return { encode: (values) => values.join('|') };
  }
}
export function demo() {
  return [new JsonJob().run([' A ', 'B']), new PipeJob().run([' A ', 'B'])];
}

interface Part {
  render(text: string): string;
}
interface DocumentKit {
  heading(): Part;
  paragraph(): Part;
}
class PlainKit implements DocumentKit {
  heading() {
    return { render: (text: string) => text.toUpperCase() };
  }
  paragraph() {
    return { render: (text: string) => text };
  }
}
class MarkdownKit implements DocumentKit {
  heading() {
    return { render: (text: string) => `# ${text}` };
  }
  paragraph() {
    return { render: (text: string) => `> ${text}` };
  }
}
function document(kit: DocumentKit) {
  return [kit.heading().render('Resumo'), kit.paragraph().render('Tudo certo')];
}
export function demo() {
  return [document(new PlainKit()), document(new MarkdownKit())];
}

type Request = { fields: string[]; destination: string };
class ExportBuilder {
  private fields: string[] = [];
  private destination = '';
  select(...fields: string[]) {
    this.fields.push(...fields);
    return this;
  }
  to(destination: string) {
    this.destination = destination;
    return this;
  }
  build(): Request {
    if (!this.fields.length || !this.destination)
      throw new Error('Pedido incompleto');
    const request = { fields: [...this.fields], destination: this.destination };
    this.fields = [];
    this.destination = '';
    return request;
  }
}
export function demo() {
  const builder = new ExportBuilder();
  const first = builder.select('nome', 'email').to('arquivo').build();
  const second = builder.select('id').to('memoria').build();
  return [first, second];
}

class FormTemplate {
  constructor(
    public title: string,
    public fields: { label: string }[],
  ) {}
  clone() {
    return new FormTemplate(
      this.title,
      this.fields.map((field) => ({ ...field })),
    );
  }
}
export function demo() {
  const original = new FormTemplate('Cadastro', [{ label: 'Nome' }]);
  const copy = original.clone();
  copy.title = 'Inscrição';
  copy.fields[0].label = 'Participante';
  return {
    original: original.fields[0].label,
    copy: copy.fields[0].label,
    independent: original.fields !== copy.fields,
  };
}

class Configuration {
  private static instance: Configuration | undefined;
  private constructor(readonly applicationName: string) {}
  static current() {
    return (this.instance ??= new Configuration('Estudos'));
  }
}
export function demo() {
  const first = Configuration.current();
  const second = Configuration.current();
  return { same: first === second, name: second.applicationName };
}
